import{_ as a,c as t,o as s,a3 as n}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Applicants","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/index.md","filePath":"master/human-resources/recruitment/applicants/index.md","lastUpdated":1793074831000}'),i={name:"master/human-resources/recruitment/applicants/index.md"};function o(r,e,l,h,p,c){return s(),t("div",null,e[0]||(e[0]=[n(`<h1 id="applicants" tabindex="-1">Applicants <a class="header-anchor" href="#applicants" aria-label="Permalink to &quot;Applicants&quot;">​</a></h1><p>An applicant is one person&#39;s application for one job position. You use applicants to follow each person from the first contact to the day they are hired or turned down. Every applicant belongs to a <a href="./candidates.html">candidate</a>, which holds the person&#39;s own details, and to a <a href="./../job-positions/job-positions.html">job position</a>.</p><blockquote><p><strong>In simple words:</strong> A candidate is the person. An applicant is that person applying for a job. You move the applicant through stages until you hire or refuse them.</p></blockquote><p>Open <code>Recruitments → Applications → Applicants</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Create the <a href="./../job-positions/job-positions.html">job position</a> people apply for.</li><li>Check the <a href="./../setup/stages.html">stages</a>. Aureus uses them as the steps of your hiring flow.</li><li>Optional: add <a href="./../setup/tags-degrees.html">tags and degrees</a>, <a href="./../setup/sources-and-mediums.html">sources and mediums</a> and <a href="./../setup/refuse-reasons.html">refuse reasons</a>.</li></ul></div><h2 id="the-hiring-flow" tabindex="-1">The hiring flow <a class="header-anchor" href="#the-hiring-flow" aria-label="Permalink to &quot;The hiring flow&quot;">​</a></h2><p>Stages are the steps an applicant goes through. In the sample data the order is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>New → First Interview → Initial Qualification → Second Interview</span></span>
<span class="line"><span>→ Document Verification → Contract Proposal → Contract Signed</span></span></code></pre></div><p>A new applicant starts in <strong>New</strong>. You move them forward by clicking the next stage on the bar at the top of the applicant page. The last stage, <strong>Contract Signed</strong>, is a <strong>Hired Stage</strong>, so reaching it hires the applicant.</p><p>Your own company can use different stages. You define them in <a href="./../setup/stages.html">Stages</a>.</p><h2 id="what-an-applicant-can-be" tabindex="-1">What an applicant can be <a class="header-anchor" href="#what-an-applicant-can-be" aria-label="Permalink to &quot;What an applicant can be&quot;">​</a></h2><p>At any moment an applicant is in one of these situations.</p><h3 id="in-a-stage" tabindex="-1">In a stage <a class="header-anchor" href="#in-a-stage" aria-label="Permalink to &quot;In a stage&quot;">​</a></h3><p>The applicant is still in the process. A small <strong>State</strong> tells you how they are doing in the current stage:</p><ul><li><strong>In Progress:</strong> you are working on them. This is the default.</li><li><strong>Ready for next stage:</strong> the work in this stage is done.</li><li><strong>Blocked:</strong> something stops the process. Blocked applicants no longer show in the main applicant list. To find them, apply the <strong>Blocked</strong> view in the <a href="./applicant-list.html">applicant list</a>.</li></ul><p>These three names are the defaults. A stage can use its own labels. See <a href="./../setup/stages.html">Stages</a>.</p><h3 id="hired" tabindex="-1">Hired <a class="header-anchor" href="#hired" aria-label="Permalink to &quot;Hired&quot;">​</a></h3><p>The applicant reached a <strong>Hired Stage</strong>. The page shows an <strong>Application status</strong> of <strong>Hired</strong> and the <strong>Hired Date</strong>. You can then <a href="./process-applicant.html#hire-the-applicant">create an employee</a>.</p><h3 id="refused" tabindex="-1">Refused <a class="header-anchor" href="#refused" aria-label="Permalink to &quot;Refused&quot;">​</a></h3><p>You turned the applicant down and gave a reason. The page shows <strong>Refused</strong>. You can bring them back with <strong>Restore</strong>. See <a href="./refuse-and-reopen.html">Refuse and reopen</a>.</p><h3 id="archived" tabindex="-1">Archived <a class="header-anchor" href="#archived" aria-label="Permalink to &quot;Archived&quot;">​</a></h3><p>An applicant that is no longer active appears under the <strong>Archived</strong> tab of the list. Refusing an applicant makes it inactive, so refused applicants show there too.</p><h2 id="pages-in-this-section" tabindex="-1">Pages in this section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in this section&quot;">​</a></h2><ul><li><a href="./add-applicant.html">Add an applicant</a>: create the application from a candidate.</li><li><a href="./process-applicant.html">Process an applicant</a>: move through stages, rate, assign and hire.</li><li><a href="./refuse-and-reopen.html">Refuse and reopen</a>: turn an applicant down, or bring them back.</li><li><a href="./applicant-list.html">Applicant list</a>: tabs, grouping, columns and filters.</li><li><a href="./candidates.html">Candidates</a>: the people behind the applications.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../dashboard/recruitment-dashboard.html">Recruitment dashboard</a></li><li><a href="./../../../getting-started/chatter.html">Chatter</a></li><li><a href="./../../../getting-started/search-filter-group.html">Search, filter and group</a></li></ul>`,26)]))}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
